// One item per image path (max 3) so each can be signed; zero images falls
// straight through with a no-image marker so the caption still gets read.
const j = $json;
if (!j || !j.job_id) return [];
const paths = (j.image_paths || []).slice(0, 3);
if (!paths.length) return [{ json: { ...j, __path: null } }];
return paths.map(p => ({ json: { ...j, __path: p } }));

// Model reply -> listing field patch + job outcome. Malformed output or an API
// error becomes a FAILED job with the reason stored; nothing retries silently.
const meta = ($('Build payload').all()[0] || {}).json || {};
// Error can be an OpenRouter body ({error:{message,metadata:{raw}}}) or, after n8n's
// retries give up (onError continueRegularOutput), a plain string. Keep the raw detail.
let apiError = null;
if ($json?.error) {
  const e = $json.error;
  apiError = (typeof e === 'string') ? e
    : [e.message || 'api error', e.code, e.metadata?.provider_name, e.metadata?.raw]
        .filter(Boolean).join(' | ');
}
let listings = null, parseError = null;
try {
  const txt = $json?.choices?.[0]?.message?.content;
  if (txt) listings = (JSON.parse(txt).listings) || [];
} catch (e) { parseError = 'bad json from model'; }

if (apiError || parseError || listings === null) {
  return [{ json: { ok: false, job_id: meta.__job_id,
    error: apiError || parseError || 'no model reply' } }];
}

const norm = (r) => (r == null ? null : String(r).toUpperCase().replace(/[^A-Z0-9/\-.]/g, '') || null);
const l = listings[0] || null;
const usedModel = $json?.model || null;

// Chatter posts classify to nothing: that is a SUCCESS (the answer is
// "not a watch listing"), parked as status 'noise' so no later stage touches it.
if (!l) {
  return [{ json: { ok: true, job_id: meta.__job_id, listing_id: meta.__listing_id,
    model: usedModel, next_status: 'noise',
    patch: { listing_type: 'OTHER', confidence: 0 },
    output: { listings: [] } } }];
}

const ref = norm(l.reference), vref = norm(l.vision_reference);
const patch = {
  listing_type: l.listing_type || 'OTHER',
  brand: l.brand || null, model: l.model || null,
  reference: ref, reference_raw: l.reference || null,
  price_usd: (typeof l.price_usd === 'number' && l.price_usd > 0) ? l.price_usd : null,
  condition: l.condition || 'UNKNOWN',
  set_completeness: l.set_completeness || 'UNKNOWN',
  year: Number.isInteger(l.year) ? l.year : null,
  confidence: Number.isInteger(l.confidence) ? l.confidence : null,
  source: meta.__had_image ? 'BOTH' : 'CAPTION',
  vision_brand: l.vision_brand || null, vision_model: l.vision_model || null,
  vision_reference: vref, vision_mismatch: !!(ref && vref && ref !== vref),
  dial_color: l.dial_color || null, dial_material: l.dial_material || null,
  bracelet: l.bracelet || null, bezel: l.bezel || null,
  case_material: l.case_material || null,
  case_size_mm: (typeof l.case_size_mm === 'number' && l.case_size_mm > 0) ? l.case_size_mm : null,
  complications: Array.isArray(l.complications) ? l.complications : null,
  has_diamonds: (typeof l.has_diamonds === 'boolean') ? l.has_diamonds : null,
  diamonds_factory: (typeof l.diamonds_factory === 'boolean') ? l.diamonds_factory : null,
  nickname: l.nickname || null,
  model_used: usedModel,
  latency_ms: meta.__t0 ? (Date.now() - meta.__t0) : null,
  tokens_in: $json?.usage?.prompt_tokens || null,
  tokens_out: $json?.usage?.completion_tokens || null,
};
return [{ json: { ok: true, job_id: meta.__job_id, listing_id: meta.__listing_id,
  model: usedModel, patch,
  next_status: meta.__had_image ? 'awaiting_verify' : 'classified',
  output: { listings } } }];
